{"file_path":"src/parse.js","content":"/**
 * Parsing of the build-graph text format into a task/dependency graph.
 *
 * Throws a `CliError` (see cli.js) carrying the exact message and exit
 * code the specification assigns to the failure it represents.
 */

import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^\d+$/

/**
 * @param {string} input Raw standard-input text.
 * @returns {{ tasks: Map<string, number>, deps: Map<string, string[]> }}
 *   `tasks` maps a task name to its cost. `deps` maps a task name to the
 *   distinct names it depends on, in the order they were first listed.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const usedNames = []

  lines.forEach((rawLine, index) => {
    const lineNumber = index + 1
    const line = rawLine.trim()
    if (line === '' || line.startsWith('#')) return

    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(2, `line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(2, `line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costText)) {
        throw new CliError(2, `line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(2, `line ${lineNumber}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costText, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(2, `line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const dependencies = words.slice(2)
      for (const candidate of [name, ...dependencies]) {
        if (!NAME_RE.test(candidate)) {
          throw new CliError(2, `line ${lineNumber}: invalid task name ${candidate}`)
        }
      }
      usedNames.push(name, ...dependencies)
      const existing = deps.get(name) ?? []
      for (const dependency of dependencies) {
        if (!existing.includes(dependency)) existing.push(dependency)
      }
      deps.set(name, existing)
    } else {
      throw new CliError(2, `line ${lineNumber}: unknown directive ${directive}`)
    }
  })

  for (const name of usedNames) {
    if (!tasks.has(name)) {
      throw new CliError(2, `unknown task ${name}`, false)
    }
  }

  return { tasks, deps }
}
"}

