{"file_path":"src/errors.js","content":"/**
 * An error whose message and exit code are already the ones the
 * specification requires; `cli.js` writes `error: <message>` to standard
 * error and exits with `code`.
 */
export class CliError extends Error {
  /**
   * @param {number} code The process exit code.
   * @param {string} message The text that follows `error: `.
   */
  constructor(code, message) {
    super(message)
    this.code = code
  }
}
"}

