{"file_path":"src/graph.js","content":"/**
 * Graph analysis over a parsed build graph: cycle detection and the
 * derived per-task numbers (start, finish, depth, priority) that the
 * `waves`, `explain` and `pack` modes report.
 */

import { CycleError } from './errors.js'

/**
 * Finds the first cycle a depth-first search reaches when it visits tasks
 * and their dependencies in ascending name order, and throws a
 * `CycleError` describing it. Returns normally when the graph is a DAG.
 *
 * @param {Map<string, number>} tasks
 * @param {Map<string, string[]>} deps
 */
export function detectCycle(tasks, deps) {
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  const visit = (name) => {
    if (onStack.has(name)) {
      const start = stack.indexOf(name)
      throw new CycleError([...stack.slice(start), name])
    }
    if (visited.has(name)) return
    onStack.add(name)
    stack.push(name)
    for (const dependency of [...(deps.get(name) ?? [])].sort()) {
      visit(dependency)
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!visited.has(name)) visit(name)
  }
}

/**
 * Computes, for every task, the start and finish time with unlimited
 * workers and the wave (depth) it sits in. The graph must already be
 * known to be acyclic.
 *
 * @param {Map<string, number>} tasks
 * @param {Map<string, string[]>} deps
 * @returns {Map<string, { start: number, finish: number, depth: number }>}
 */
export function computeTimings(tasks, deps) {
  const timings = new Map()

  const timingOf = (name) => {
    const cached = timings.get(name)
    if (cached) return cached
    const dependencies = deps.get(name) ?? []
    let start = 0
    let depth = 0
    for (const dependency of dependencies) {
      const dependencyTiming = timingOf(dependency)
      if (dependencyTiming.finish > start) start = dependencyTiming.finish
      if (dependencyTiming.depth + 1 > depth) depth = dependencyTiming.depth + 1
    }
    const finish = start + tasks.get(name)
    const timing = { start, finish, depth }
    timings.set(name, timing)
    return timing
  }

  for (const name of tasks.keys()) timingOf(name)
  return timings
}

/**
 * Computes, for every task, the cost of the longest chain that begins at
 * it and continues through the tasks that (transitively) depend on it.
 *
 * @param {Map<string, number>} tasks
 * @param {Map<string, string[]>} deps
 * @returns {Map<string, number>}
 */
export function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, dependencies] of deps) {
    for (const dependency of dependencies) {
      dependents.get(dependency)?.push(name)
    }
  }

  const priorities = new Map()

  const priorityOf = (name) => {
    const cached = priorities.get(name)
    if (cached !== undefined) return cached
    let downstream = 0
    for (const dependent of dependents.get(name)) {
      const dependentPriority = priorityOf(dependent)
      if (dependentPriority > downstream) downstream = dependentPriority
    }
    const priority = tasks.get(name) + downstream
    priorities.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) priorityOf(name)
  return priorities
}
"}

