{"file_path":"src/pack.js","content":"/**
 * The `pack <workers>` simulation: greedily assigns ready tasks to free
 * workers, highest priority first, until every task has run.
 */

import { computePriorities } from './graph.js'

/**
 * @param {Map<string, number>} tasks
 * @param {Map<string, string[]>} deps
 * @param {number} workerCount
 * @returns {{ runs: { name: string, start: number, finish: number }[][], makespan: number }}
 *   `runs[i]` is the ordered list of tasks worker `i` ran.
 */
export function pack(tasks, deps, workerCount) {
  const priorities = computePriorities(tasks, deps)
  const names = [...tasks.keys()].sort()
  const finishOf = new Map()
  const started = new Set()
  const runs = Array.from({ length: workerCount }, () => [])
  const freeAt = new Array(workerCount).fill(0)

  const isReady = (name) => (deps.get(name) ?? []).every((dependency) => finishOf.has(dependency))
  const readyAt = (name, time) =>
    (deps.get(name) ?? []).every((dependency) => (finishOf.get(dependency) ?? 0) <= time)

  let currentTime = 0
  let makespan = 0

  while (started.size < names.length) {
    let progressed = true
    while (progressed) {
      progressed = false
      let workerIndex = -1
      for (let i = 0; i < workerCount; i += 1) {
        if (freeAt[i] <= currentTime) {
          workerIndex = i
          break
        }
      }
      if (workerIndex === -1) break

      let chosen = null
      for (const name of names) {
        if (started.has(name)) continue
        if (!readyAt(name, currentTime)) continue
        if (chosen === null || priorities.get(name) > priorities.get(chosen)) chosen = name
      }
      if (chosen === null) break

      const start = currentTime
      const finish = start + tasks.get(chosen)
      started.add(chosen)
      finishOf.set(chosen, finish)
      freeAt[workerIndex] = finish
      runs[workerIndex].push({ name: chosen, start, finish })
      if (finish > makespan) makespan = finish
      progressed = true
    }

    if (started.size >= names.length) break

    let next = Infinity
    for (let i = 0; i < workerCount; i += 1) {
      if (freeAt[i] > currentTime && freeAt[i] < next) next = freeAt[i]
    }
    currentTime = next
  }

  void isReady
  return { runs, makespan }
}
"}

