#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read
 * from standard input.
 */

import { CliError, CycleError } from './errors.js'
import { parseGraph } from './parse.js'
import { detectCycle, computeTimings } from './graph.js'
import { pack } from './pack.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9]\d*$/

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError(2, 'workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(2, USAGE)
}

function renderWaves(timings) {
  const byDepth = new Map()
  let total = 0
  for (const [name, timing] of timings) {
    const bucket = byDepth.get(timing.depth) ?? []
    bucket.push(name)
    byDepth.set(timing.depth, bucket)
    if (timing.finish > total) total = timing.finish
  }

  const lines = []
  const maxDepth = byDepth.size === 0 ? -1 : Math.max(...byDepth.keys())
  for (let depth = 0; depth <= maxDepth; depth += 1) {
    const names = (byDepth.get(depth) ?? []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderExplain(tasks, timings) {
  let total = 0
  for (const timing of timings.values()) {
    if (timing.finish > total) total = timing.finish
  }
  const lines = [...tasks.keys()].sort().map((name) => {
    const { start, finish, depth } = timings.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderPack(tasks, deps, workerCount) {
  const { runs, makespan } = pack(tasks, deps, workerCount)
  const lines = runs.map((run, index) => {
    const entries = run.map(({ name, start, finish }) => ` ${name}@${start}-${finish}`).join('')
    return `worker ${index}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)
  const input = await readStdin()
  const { tasks, deps } = parseGraph(input)
  detectCycle(tasks, deps)

  if (args.mode === 'waves') {
    process.stdout.write(renderWaves(computeTimings(tasks, deps)))
  } else if (args.mode === 'explain') {
    process.stdout.write(renderExplain(tasks, computeTimings(tasks, deps)))
  } else {
    process.stdout.write(renderPack(tasks, deps, args.workers))
  }
}

main().catch((error) => {
  if (error instanceof CycleError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(3)
  }
  if (error instanceof CliError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
  }
  throw error
})
